/** Zwei kurze Absätze je Rahmenwerk für die aufklappbare Sektion auf der Detailseite. */
export const ABOUT_LONG: Record<string, [Txt, Txt]> = {
  dora: [
    {de:"DORA verpflichtet Finanzunternehmen, IKT-Risiken als eigenständige Risikokategorie zu steuern: von der Governance über das Management des gesamten IKT-Lebenszyklus bis zur Klassifizierung und Meldung schwerwiegender Vorfälle innerhalb fester Fristen. Die Verordnung gilt unmittelbar und ersetzt einen Flickenteppich nationaler Vorgaben.",
     en:"DORA obliges financial entities to manage ICT risk as a risk category in its own right: from governance through the full ICT lifecycle to classifying and reporting major incidents within fixed deadlines. The regulation applies directly and replaces a patchwork of national requirements."},
    {de:"Neu ist die EU-weite Überwachung kritischer IKT-Drittdienstleister wie Cloud-Anbieter durch die europäischen Aufsichtsbehörden sowie die Pflicht zu bedrohungsgeleiteten Penetrationstests (TLPT) für bedeutende Institute. Verträge mit IT-Dienstleistern müssen Mindestinhalte erfüllen und in einem Informationsregister geführt werden.",
     en:"New is the EU-wide oversight of critical ICT third-party providers such as cloud providers by the European supervisory authorities, plus mandatory threat-led penetration testing (TLPT) for significant institutions. Contracts with IT providers must meet minimum content requirements and be kept in a register of information."}],
  nis2: [
    {de:"NIS2 weitet die europäischen Cybersicherheitspflichten auf deutlich mehr Sektoren und Unternehmen aus und unterscheidet zwischen wesentlichen und wichtigen Einrichtungen. Verlangt werden Risikomanagementmaßnahmen nach dem Stand der Technik, Lieferkettensicherheit und eine gestufte Meldung erheblicher Sicherheitsvorfälle.",
     en:"NIS2 extends European cybersecurity duties to far more sectors and companies, distinguishing between essential and important entities. It requires state-of-the-art risk management measures, supply chain security and staged reporting of significant incidents."},
    {de:"In Deutschland erfolgt die Umsetzung über das NIS2-Umsetzungsgesetz im BSI-Gesetz; die Geschäftsleitung haftet persönlich für die Billigung und Überwachung der Maßnahmen. Für Finanzunternehmen gilt der Grundsatz, dass DORA als spezielleres Regime vorgeht.",
     en:"In Germany, implementation happens through the NIS2 Implementation Act within the BSI Act; management is personally liable for approving and overseeing the measures. For financial entities, DORA takes precedence as the more specific regime."}],
  ebaict: [
    {de:"Die EBA-Leitlinien konkretisieren, wie Institute IKT- und Sicherheitsrisiken identifizieren, bewerten und mindern sollen: Informationssicherheits-Leitlinie, Rollentrennung, Zugriffsmanagement, Schwachstellen- und Patch-Prozesse sowie Sensibilisierung der Mitarbeitenden.",
     en:"The EBA guidelines specify how institutions should identify, assess and mitigate ICT and security risks: an information security policy, segregation of duties, access management, vulnerability and patch processes, and staff awareness."},
    {de:"Sie bilden die Brücke zwischen den allgemeinen Organisationspflichten aus MaRisk und den detaillierten DORA-Anforderungen und werden von BaFin und EZB in der laufenden Aufsicht als Prüfungsmaßstab herangezogen.",
     en:"They bridge the general organisational duties under MaRisk and the detailed DORA requirements, and are used by BaFin and the ECB as a benchmark in ongoing supervision."}],
  amla: [
    {de:"Das neue EU-Geldwäschepaket verlagert die zentralen Sorgfalts-, Melde- und Transparenzpflichten in eine unmittelbar geltende Verordnung und harmonisiert damit erstmals das materielle Geldwäscherecht in der gesamten Union. Nationale Spielräume werden deutlich reduziert.",
     en:"The new EU AML package moves the core due diligence, reporting and transparency duties into a directly applicable regulation, harmonising substantive AML law across the Union for the first time. National discretion is significantly reduced."},
    {de:"Die neue Behörde AMLA mit Sitz in Frankfurt erlässt technische Standards, koordiniert die nationalen Aufseher und beaufsichtigt ab 2028 ausgewählte, besonders risikoreiche Verpflichtete direkt. Institute sollten ihre Kundenannahme- und Monitoring-Prozesse frühzeitig auf das neue Regelwerk ausrichten.",
     en:"The new AMLA authority, seated in Frankfurt, issues technical standards, coordinates national supervisors and, from 2028, directly supervises selected high-risk obliged entities. Institutions should align their onboarding and monitoring processes with the new rulebook early."}],
  gwg: [
    {de:"Das Geldwäschegesetz verpflichtet Institute zu einem risikobasierten Ansatz: Risikoanalyse, interne Sicherungsmaßnahmen, Bestellung eines Geldwäschebeauftragten sowie allgemeine und verstärkte Sorgfaltspflichten gegenüber Kunden und wirtschaftlich Berechtigten.",
     en:"The Money Laundering Act requires a risk-based approach: a risk analysis, internal safeguards, appointment of an AML officer, and standard and enhanced due diligence towards customers and beneficial owners."},
    {de:"Verdachtsfälle sind unverzüglich elektronisch an die FIU zu melden; daneben bestehen Aufzeichnungs- und Aufbewahrungspflichten sowie die Pflicht zur Meldung an das Transparenzregister. Mit Geltung der EU-Geldwäscheverordnung wird das GwG auf ergänzende nationale Regelungen zurückgeschnitten.",
     en:"Suspicious activity must be reported electronically to the FIU without delay; record-keeping and retention duties and transparency register filings apply alongside. Once the EU AML Regulation applies, the GwG will be cut back to supplementary national rules."}],
  crr3: [
    {de:"CRR III setzt die finalen Basel-III-Standards in der EU um. Kernstück ist der Output Floor: Interne Modelle dürfen die Eigenmittelanforderungen langfristig nur noch auf 72,5 % des Standardansatzes senken, mit Übergangsregelungen bis 2030.",
     en:"CRR III implements the final Basel III standards in the EU. Its centrepiece is the output floor: internal models may ultimately reduce own funds requirements to no less than 72.5% of the standardised approach, with transitional arrangements until 2030."},
    {de:"Daneben werden Kreditrisiko-Standardansatz und IRB-Ansatz granularer, das operationelle Risiko erhält einen einheitlichen Standardansatz und das Marktrisiko wird über FRTB neu geregelt. Institute müssen Datenhaushalt und Meldewesen entsprechend umbauen.",
     en:"In addition, the standardised and IRB approaches for credit risk become more granular, operational risk moves to a single standardised approach and market risk is overhauled via FRTB. Institutions must rebuild their data and reporting accordingly."}],
  marisk: [
    {de:"Die MaRisk übersetzen die allgemeinen Organisationspflichten des § 25a KWG in konkrete Anforderungen: Strategie- und Risikotragfähigkeitsprozesse, Funktionstrennung, Interne Revision sowie besondere Anforderungen an Kredit- und Handelsgeschäft.",
     en:"MaRisk translates the general organisational duties of § 25a KWG into concrete requirements: strategy and risk-bearing capacity processes, segregation of functions, internal audit, and specific requirements for lending and trading."},
    {de:"Als Verwaltungsanweisung mit Öffnungsklauseln folgen sie dem Proportionalitätsprinzip und werden regelmäßig novelliert, zuletzt etwa um ESG-Risiken, Immobiliengeschäfte und die EBA-Leitlinien zur Kreditvergabe. Für Prüfungen der Bankenaufsicht sind sie der zentrale Maßstab.",
     en:"As administrative guidance with opening clauses, it follows the proportionality principle and is amended regularly — most recently to cover ESG risks, real estate business and the EBA loan origination guidelines. It is the central benchmark for supervisory examinations."}],
  brrd: [
    {de:"Das Sanierungs- und Abwicklungsregime verpflichtet Institute zu Sanierungsplänen und die Abwicklungsbehörden zu Abwicklungsplänen, damit ein Ausfall ohne Steuergelder bewältigt werden kann. Kernelement ist das Bail-in-Instrument, das Verluste zunächst Eigentümern und Gläubigern zuweist.",
     en:"The recovery and resolution regime requires institutions to draw up recovery plans and resolution authorities to prepare resolution plans, so a failure can be managed without taxpayer money. The core element is the bail-in tool, which allocates losses first to owners and creditors."},
    {de:"Über MREL müssen Institute jederzeit ausreichend berücksichtigungsfähige Verbindlichkeiten vorhalten. Für bedeutende Institute der Bankenunion liegt die Zuständigkeit beim Einheitlichen Abwicklungsausschuss (SRB), national bei der BaFin als Abwicklungsbehörde.",
     en:"Through MREL, institutions must maintain sufficient eligible liabilities at all times. For significant banking union institutions, responsibility lies with the Single Resolution Board (SRB); nationally, BaFin acts as resolution authority."}],
  ifr: [
    {de:"Das IFR/IFD-Regime löst Wertpapierinstitute aus der Bankenregulierung heraus und bemisst die Eigenmittelanforderungen über K-Faktoren, die kunden-, markt- und firmenbezogene Risiken der tatsächlichen Geschäftstätigkeit abbilden.",
     en:"The IFR/IFD regime carves investment firms out of banking regulation and sizes own funds requirements via K-factors that capture risk-to-client, risk-to-market and risk-to-firm from the actual business."},
    {de:"Kleine und nicht verflochtene Institute profitieren von Erleichterungen bei Offenlegung, Vergütung und Meldewesen, während sehr große Häuser mit bankähnlichem Geschäft wieder unter die CRR fallen. In Deutschland ist das Regime im WpIG umgesetzt.",
     en:"Small and non-interconnected firms benefit from relief on disclosure, remuneration and reporting, while very large firms with bank-like business fall back under the CRR. In Germany the regime is implemented in the WpIG."}],
  outsourcing: [
    {de:"Auslagerungen entbinden nicht von der Verantwortung: Institute müssen Risiken vor Vertragsschluss bewerten, Weisungs-, Auskunfts- und Prüfungsrechte vereinbaren und ausgelagerte Prozesse laufend überwachen — bei wesentlichen Auslagerungen mit erhöhten Anforderungen.",
     en:"Outsourcing does not transfer responsibility: institutions must assess risks before contracting, secure instruction, information and audit rights, and continuously monitor outsourced processes — with heightened requirements for critical arrangements."},
    {de:"Sämtliche Auslagerungen sind in einem Register zu dokumentieren; wesentliche Auslagerungen und deren Weiterverlagerungen sind der Aufsicht anzuzeigen. Mit DORA treten für IKT-Dienstleistungen zusätzliche vertragliche Mindestinhalte und das Informationsregister hinzu.",
     en:"All arrangements must be documented in a register; critical outsourcing and its subcontracting must be notified to the supervisor. With DORA, ICT services additionally require minimum contractual content and the register of information."}],
  hinschg: [
    {de:"Das Hinweisgeberschutzgesetz verpflichtet Beschäftigungsgeber ab 50 Mitarbeitenden — Finanzdienstleister unabhängig von der Größe — zu internen Meldestellen, über die Verstöße vertraulich, auf Wunsch auch anonym, gemeldet werden können.",
     en:"The Whistleblower Protection Act obliges employers with 50 or more staff — financial firms regardless of size — to operate internal reporting channels through which breaches can be reported confidentially, and on request anonymously."},
    {de:"Hinweisgebende Personen sind vor Repressalien wie Kündigung oder Benachteiligung geschützt; bei Verstößen greift eine Beweislastumkehr zugunsten der meldenden Person. Eingänge sind fristgebunden zu bestätigen und zu bearbeiten sowie datenschutzkonform zu dokumentieren.",
     en:"Reporting persons are protected against retaliation such as dismissal or disadvantage; in disputes, the burden of proof shifts in their favour. Reports must be acknowledged and processed within set deadlines and documented in line with data protection law."}],
  zagmarisk: [
    {de:"Mit dem Rundschreiben 07/2024 (BA) hat die BaFin erstmals eigene Mindestanforderungen an das Risikomanagement von Zahlungs- und E-Geld-Instituten aufgestellt. Sie folgen dem Aufbau der Banken-MaRisk mit einem Allgemeinen Teil (Organisation, Risikosteuerung, Auslagerung, IT) und Besonderen Teilen, sind aber auf die Geschäftsmodelle von ZAG-Instituten zugeschnitten: Sicherung von Kundengeldern, Betrugsprävention, Sicherheitsvorfälle, Haftungsrisiken, Kundenbeschwerden und Agentensteuerung.",
     en:"With Circular 07/2024 (BA), BaFin for the first time set out standalone minimum risk management requirements for payment and e-money institutions. They follow the structure of the banking MaRisk with a general part (organisation, risk control, outsourcing, IT) and special parts, but are tailored to ZAG business models: safeguarding of client funds, fraud prevention, security incidents, liability risks, customer complaints and agent management."},
    {de:"Rechtsgrundlage ist § 27 Abs. 1 ZAG; daneben konkretisiert das Rundschreiben die Sicherungsanforderungen der §§ 17, 18 ZAG und die Auslagerungsregeln des § 26 ZAG. Die früheren IT-Anforderungen (ZAIT) wurden mit dem Geltungsbeginn von DORA am 17.01.2025 aufgehoben, sodass ZAG-MaRisk und DORA gemeinsam den Rahmen für Governance und operationelle Resilienz bilden.",
     en:"The legal basis is § 27(1) ZAG; the circular also specifies the safeguarding requirements of §§ 17, 18 ZAG and the outsourcing rules of § 26 ZAG. The former IT requirements (ZAIT) were repealed when DORA became applicable on 17 Jan 2025, so ZAG-MaRisk and DORA together form the framework for governance and operational resilience."}],
  zag: [
    {de:"Das ZAG bestimmt, welche Tätigkeiten erlaubnispflichtige Zahlungsdienste sind: Ein- und Auszahlungsgeschäft, Zahlungsgeschäft mit und ohne Kreditgewährung, Akquisitionsgeschäft (Issuing und Acquiring), Finanztransfergeschäft, Zahlungsauslöse- und Kontoinformationsdienste sowie das E-Geld-Geschäft. Der Negativkatalog des § 2 ZAG nimmt unter anderem Handelsvertreter, begrenzte Netze und rein technische Infrastrukturdienste aus. Reine Kontoinformationsdienste werden nur registriert (§ 34 ZAG). Die BaFin erläutert die Abgrenzung in ihrem Merkblatt zum ZAG (Stand Juli 2024).",
     en:"The ZAG defines which activities are payment services requiring authorisation: cash placement and withdrawal, payment transactions with and without credit, acquiring and issuing, money remittance, payment initiation and account information services, and e-money business. The negative list in § 2 ZAG exempts, among others, commercial agents, limited networks and purely technical infrastructure services. Pure account information services are only registered (§ 34 ZAG). BaFin explains the delineation in its guidance note on the ZAG (as of July 2024)."},
    {de:"In der laufenden Aufsicht stehen Eigenmittel nach der ZAG-Instituts-Eigenmittelverordnung, die Sicherung entgegengenommener Gelder nach § 17 ZAG, die Einbindung und Anzeige von Agenten, Auslagerungen nach § 26 ZAG sowie die Anzeige- und Meldepflichten der ZAG-Anzeigenverordnung und der ZAG-Monatsausweisverordnung im Mittelpunkt. Hinzu kommen die jährliche Bewertung operationeller und sicherheitsrelevanter Risiken, die Meldung schwerwiegender Vorfälle und die Betrugsstatistik nach der Delegierten Verordnung (EU) 2018/389.",
     en:"Ongoing supervision centres on own funds under the ZAG own funds ordinance, safeguarding of received funds under § 17 ZAG, the engagement and notification of agents, outsourcing under § 26 ZAG, and the notification and reporting duties of the ZAG notification ordinance and the monthly return ordinance. In addition, institutions must assess operational and security risks annually, report major incidents and submit fraud statistics under Delegated Regulation (EU) 2018/389."}],
  macomp: [
    {de:"Die MaComp bündeln die Verwaltungspraxis der BaFin zu den Organisations- und Wohlverhaltensregeln des WpHG für Wertpapierdienstleistungsunternehmen. Der Allgemeine Teil regelt die Compliance-Funktion: Stellung und Unabhängigkeit des Compliance-Beauftragten, Überwachungsplan, Berichterstattung an Geschäftsleitung und Aufsichtsorgan sowie die Einbindung in Neuprodukt- und Auslagerungsprozesse.",
     en:"The MaComp consolidate BaFin's administrative practice on the WpHG organisational and conduct rules for investment services firms. The general part governs the compliance function: position and independence of the compliance officer, monitoring plan, reporting to management and the supervisory body, and involvement in new product and outsourcing processes."},
    {de:"Die Besonderen Teile übersetzen ESMA-Leitlinien in konkrete Anforderungen, etwa zu Produktüberwachung (BT 5), Geeignetheitsprüfung (BT 7), Zuwendungen, Aufzeichnung von Telefongesprächen und Mitarbeitergeschäften. Die BaFin aktualisiert die MaComp laufend, zuletzt im September 2024 zur Berücksichtigung von Nachhaltigkeitspräferenzen.",
     en:"The special parts translate ESMA guidelines into concrete requirements, for example on product governance (BT 5), suitability assessment (BT 7), inducements, recording of telephone conversations and personal transactions. BaFin updates the MaComp on an ongoing basis, most recently in September 2024 to reflect sustainability preferences."}],
  instvergv: [
    {de:"Die Institutsvergütungsverordnung konkretisiert § 25a KWG: Vergütungssysteme müssen auf die Strategie ausgerichtet sein und dürfen keine Anreize zu unangemessenen Risiken setzen. Bedeutende Institute identifizieren Risikoträger, deren variable Vergütung zeitlich gestreckt, teilweise in Instrumenten gewährt und im Fall von Fehlverhalten zurückgefordert wird; ein Vergütungskontrollausschuss und ein Vergütungsbeauftragter überwachen die Angemessenheit.",
     en:"The remuneration ordinance specifies § 25a KWG: pay systems must be aligned with strategy and must not incentivise excessive risk-taking. Significant institutions identify material risk takers whose variable pay is deferred, partly paid in instruments and subject to clawback in case of misconduct; a remuneration committee and a remuneration officer monitor appropriateness."},
    {de:"Die Verordnung setzt die Vergütungsvorgaben der CRD und die EBA-Leitlinien zu soliden Vergütungspolitiken um; für Wertpapierinstitute gilt die parallele WpI-Vergütungsverordnung. Anpassungen aus CRD VI und der Bürokratieentlastung wurden 2026 nachgezogen. Vergütungsberichte sind jährlich offenzulegen.",
     en:"The ordinance implements the CRD remuneration provisions and the EBA guidelines on sound remuneration policies; investment firms fall under the parallel WpI remuneration ordinance. Adjustments from CRD VI and the bureaucracy relief package followed in 2026. Remuneration reports must be disclosed annually."}],
  sanctions: [
    {de:"EU-Sanktionsverordnungen gelten unmittelbar und verpflichten alle Unternehmen, Gelder und wirtschaftliche Ressourcen gelisteter Personen einzufrieren und ihnen nichts bereitzustellen. Für Finanzinstitute bedeutet das laufendes Screening von Kunden, Zahlungen und Geschäftspartnern gegen die konsolidierte EU-Sanktionsliste sowie die unverzügliche Meldung eingefrorener Gelder an das Servicezentrum Finanzsanktionen der Bundesbank.",
     en:"EU sanctions regulations apply directly and oblige all companies to freeze funds and economic resources of listed persons and to make nothing available to them. For financial institutions this means ongoing screening of customers, payments and counterparties against the consolidated EU sanctions list and prompt reporting of frozen funds to the Bundesbank's Financial Sanctions Service Centre."},
    {de:"Verstöße sind nach dem Außenwirtschaftsgesetz strafbar oder bußgeldbewehrt. Mit den Sanktionsdurchsetzungsgesetzen wurde die Zentralstelle für Sanktionsdurchsetzung geschaffen und die Ermittlungs- und Meldeinfrastruktur ausgebaut; die Sanktionspakete gegen Russland haben Umfang und Änderungsfrequenz der Vorgaben deutlich erhöht.",
     en:"Breaches are criminal or administrative offences under the Foreign Trade and Payments Act. The Sanctions Enforcement Acts created the Central Office for Sanctions Enforcement and expanded the investigation and reporting infrastructure; the sanctions packages against Russia have markedly increased the scope and frequency of change."}],
  tfr: [
    {de:"Die Geldtransfer-Verordnung verpflichtet Zahlungsdienstleister, jeden Geldtransfer mit vollständigen Angaben zu Auftraggeber und Begünstigtem zu versehen, diese Angaben zu prüfen und bei fehlenden Daten den Transfer zurückzuweisen oder auszusetzen. Sie ist das Werkzeug, mit dem Zahlungsketten für die Geldwäscheprävention rückverfolgbar bleiben.",
     en:"The Transfer of Funds Regulation obliges payment service providers to accompany every transfer with complete information on payer and payee, to verify that information and to reject or suspend transfers with missing data. It is the tool that keeps payment chains traceable for anti-money-laundering purposes."},
    {de:"Mit der Neufassung 2023 gilt die sogenannte Travel Rule auch für Kryptowertetransfers: Anbieter von Kryptowerte-Dienstleistungen müssen Angaben zu Absender und Empfänger erheben, weitergeben und bei Transfers mit nicht gehosteten Wallets zusätzliche Prüfungen vornehmen. Die EBA hat dazu Leitlinien zur Umsetzung veröffentlicht.",
     en:"With the 2023 recast, the so-called travel rule also applies to transfers of crypto-assets: crypto-asset service providers must collect and transmit originator and beneficiary information and carry out additional checks for transfers involving self-hosted wallets. The EBA has issued guidelines on implementation."}],
  dgsd: [
    {de:"Die Einlagensicherungsrichtlinie garantiert jedem Einleger 100.000 Euro je Institut und legt Beitragspflichten, Zielausstattung und Auszahlungsfristen der Sicherungssysteme fest. In Deutschland setzt das Einlagensicherungsgesetz die Vorgaben um; CRR-Kreditinstitute müssen ihre Einleger über Umfang und Grenzen des Schutzes informieren.",
     en:"The Deposit Guarantee Schemes Directive guarantees every depositor 100,000 euros per institution and sets contribution duties, target funding levels and payout deadlines for the schemes. In Germany the Deposit Guarantee Act transposes the rules; CRR credit institutions must inform their depositors about the scope and limits of protection."},
    {de:"Das 2026 im Amtsblatt veröffentlichte CMDI-Paket reformiert Einlagensicherung und Abwicklung gemeinsam: Der Schutzumfang wird erweitert, die Einlegerhierarchie in der Insolvenz angepasst und der Einsatz von Sicherungsmitteln in der Abwicklung erleichtert. Die Änderungen sind nach 24 Monaten Übergangsfrist anzuwenden.",
     en:"The CMDI package published in the Official Journal in 2026 reforms deposit insurance and resolution together: coverage is extended, the depositor hierarchy in insolvency is adjusted and the use of guarantee scheme funds in resolution is facilitated. The changes apply after a 24-month transition period."}],
  prospectus: [
    {de:"Wer Wertpapiere öffentlich anbietet oder zum Handel an einem geregelten Markt zulassen lässt, braucht grundsätzlich einen von der BaFin gebilligten Prospekt. Die Prospektverordnung regelt Inhalt, Format, Zusammenfassung, Nachträge und Haftung; unterhalb bestimmter Schwellen genügen Wertpapier-Informationsblätter nach dem WpPG.",
     en:"Anyone offering securities to the public or seeking admission to trading on a regulated market generally needs a prospectus approved by BaFin. The Prospectus Regulation governs content, format, summary, supplements and liability; below certain thresholds, securities information sheets under the WpPG suffice."},
    {de:"Der EU Listing Act von 2024 vereinfacht das Regime: höhere Schwellen für prospektfreie Angebote, standardisierte und kürzere Prospekte, Erleichterungen für Sekundäremissionen sowie flankierende Änderungen an Marktmissbrauchsverordnung und MiFIR. Für Emissionsbegleiter ändern sich damit Prüf- und Dokumentationsprozesse.",
     en:"The 2024 EU Listing Act simplifies the regime: higher thresholds for prospectus-exempt offers, standardised and shorter prospectuses, relief for secondary issuances and accompanying changes to the Market Abuse Regulation and MiFIR. For underwriters this changes review and documentation processes."}],
  csdr: [
    {de:"Die Zentralverwahrerverordnung regelt neben der Zulassung von Zentralverwahrern die Abwicklungsdisziplin: Geldbußen bei gescheiterten Abwicklungen, Meldung von Abwicklungsausfällen und die Berichterstattung über internalisierte Abwicklung. Depotbanken und Handelsteilnehmer müssen ihre Prozesse entsprechend ausrichten.",
     en:"Beyond authorising central securities depositories, the CSDR governs settlement discipline: cash penalties for settlement fails, reporting of fails and reporting on internalised settlement. Custodians and trading participants must align their processes accordingly."},
    {de:"Ab dem 11.10.2027 verkürzt sich der verbindliche Abwicklungszyklus in der EU von T+2 auf T+1. Das erfordert beschleunigte Abgleich-, Bestätigungs- und Finanzierungsprozesse am Handelstag, angepasste Cut-off-Zeiten und die Koordination mit Großbritannien und der Schweiz, die zeitgleich umstellen.",
     en:"From 11 Oct 2027 the mandatory settlement cycle in the EU shortens from T+2 to T+1. This requires accelerated matching, confirmation and funding processes on trade date, adjusted cut-off times and coordination with the UK and Switzerland, which switch at the same time."}],
  crs: [
    {de:"Finanzinstitute müssen die steuerliche Ansässigkeit ihrer Kontoinhaber feststellen und meldepflichtige Konten jährlich an das Bundeszentralamt für Steuern melden: nach dem Common Reporting Standard über das Finanzkonten-Informationsaustauschgesetz und für US-Personen nach dem FATCA-Abkommen. Sorgfaltspflichten bei Kontoeröffnung und Selbstauskünfte sind dafür fest im Onboarding zu verankern.",
     en:"Financial institutions must determine the tax residency of their account holders and report reportable accounts annually to the Federal Central Tax Office: under the Common Reporting Standard via the Financial Account Information Exchange Act and, for US persons, under the FATCA agreement. Due diligence at account opening and self-certifications must be embedded in onboarding."},
    {de:"Mit DAC8 und dem Kryptowerte-Steuertransparenzgesetz gelten seit 2026 vergleichbare Sorgfalts- und Meldepflichten für Anbieter von Kryptowerte-Dienstleistungen; zugleich wurde der CRS auf E-Geld und digitales Zentralbankgeld ausgeweitet. Erste Meldungen für das Jahr 2026 sind 2027 fällig.",
     en:"With DAC8 and the Crypto-Asset Tax Transparency Act, comparable due diligence and reporting duties apply to crypto-asset service providers since 2026; at the same time the CRS was extended to e-money and central bank digital currencies. First reports for 2026 are due in 2027."}],
  fida: [
    {de:"FiDA soll den Kontozugang der PSD2 auf weitere Finanzdaten ausdehnen: Hypotheken, Kredite, Spar- und Anlageprodukte, Versicherungen und Altersvorsorge. Dateninhaber müssten Kundendaten auf Wunsch der Kunden über Schnittstellen mit zugelassenen Datennutzern teilen, organisiert in Datenaustauschsystemen mit Vergütungs- und Haftungsregeln.",
     en:"FiDA is meant to extend PSD2 account access to further financial data: mortgages, loans, savings and investment products, insurance and pensions. Data holders would have to share customer data at the customer's request with authorised data users via interfaces, organised in data-sharing schemes with compensation and liability rules."},
    {de:"Der Kommissionsvorschlag stammt aus dem Juni 2023. Parlament und Rat haben ihre Positionen 2024 festgelegt, der Trilog ruht jedoch seit Sommer 2025; mehrere Mitgliedstaaten drängen nicht auf einen Abschluss. Bei einer Verabschiedung wären Übergangsfristen von 18 bis 24 Monaten zu erwarten.",
     en:"The Commission proposal dates from June 2023. Parliament and Council adopted their positions in 2024, but the trilogue has been on hold since summer 2025; several member states are not pushing for a conclusion. If adopted, transition periods of 18 to 24 months are to be expected."}],
  zkg: [
    {de:"Das Zahlungskontengesetz gibt jedem Verbraucher mit rechtmäßigem Aufenthalt in der EU einen Anspruch auf ein Basiskonto bei jedem Institut, das Zahlungskonten für Verbraucher anbietet; Ablehnungen sind nur aus gesetzlich benannten Gründen zulässig und können bei der BaFin überprüft werden. Die Kontowechselhilfe verpflichtet altes und neues Institut zu einem standardisierten Wechselprozess mit festen Fristen.",
     en:"The Payment Accounts Act gives every consumer legally resident in the EU a right to a basic account at any institution offering consumer payment accounts; refusals are permitted only on statutory grounds and can be reviewed by BaFin. The account switching service obliges old and new institution to a standardised switching process with fixed deadlines."},
    {de:"Entgeltinformation vor Vertragsschluss und jährliche Entgeltaufstellung müssen die standardisierten EU-Begriffe verwenden; die BaFin überwacht die Einhaltung und kann Basiskontoentgelte auf Angemessenheit prüfen. Für Compliance sind vor allem Ablehnungsprozesse, Fristenkontrolle beim Kontowechsel und die Vollständigkeit der Entgeltdokumente relevant.",
     en:"The pre-contractual fee information document and the annual statement of fees must use the standardised EU terminology; BaFin monitors compliance and can review basic account fees for reasonableness. For compliance, the key points are refusal processes, deadline control in account switching and completeness of fee documents."}],
  interchange: [
    {de:"Die Interbankenentgelte-Verordnung deckelt seit Dezember 2015 die Entgelte, die der Acquirer an den kartenausgebenden Zahlungsdienstleister zahlt: 0,2 Prozent bei Verbraucher-Debitkarten und 0,3 Prozent bei Verbraucher-Kreditkarten. Firmenkarten und Drei-Parteien-Systeme sind teilweise ausgenommen.",
     en:"Since December 2015 the Interchange Fee Regulation caps the fees the acquirer pays to the card-issuing payment service provider: 0.2 percent for consumer debit cards and 0.3 percent for consumer credit cards. Commercial cards and three-party schemes are partly exempt."},
    {de:"Daneben enthält sie Geschäftsregeln: Trennung von Kartensystem und Abwicklungsdienstleister, Verbot von Gebietsbeschränkungen bei Lizenzen, Wahlfreiheit der Zahlungsmarke am Terminal, Verbot der Pflicht zur Akzeptanz aller Karten sowie aufgeschlüsselte Entgeltinformation für Händler. Die Einhaltung überwacht in Deutschland die BaFin.",
     en:"It also sets business rules: separation of scheme and processing entity, ban on territorial licensing restrictions, choice of payment brand at the terminal, ban on honour-all-cards obligations and itemised fee information for merchants. In Germany, compliance is monitored by BaFin."}],
  complaints: [
    {de:"Beschwerden sind ein aufsichtlich vorgeschriebener Frühwarnindikator: Institute müssen eine Beschwerdemanagementfunktion einrichten, jede Beschwerde in einem internen Register erfassen, sie objektiv und fristgerecht bearbeiten und die Beschwerdeführer über Verfahren, Ergebnis und außergerichtliche Streitbeilegung informieren. Die Auswertung der Beschwerden fließt in die Produktüberwachung und die Berichterstattung an die Geschäftsleitung ein.",
     en:"Complaints are a supervisory early-warning indicator: institutions must set up a complaints management function, record every complaint in an internal register, handle it objectively and within deadlines, and inform complainants about the procedure, outcome and out-of-court dispute resolution. Complaints analysis feeds into product governance and reporting to management."},
    {de:"Rechtlicher Rahmen sind die Leitlinien des Joint Committee der ESAs (JC 2014/43, erweitert durch JC 2018/35) und die EIOPA-Leitlinien für Versicherer und Vermittler. In Deutschland setzt sie das gemeinsame BaFin-Rundschreiben 06/2018 für Kreditinstitute, Zahlungs- und E-Geld-Institute, KVGen und Wohnimmobilienkreditgeber um; für Wertpapierdienstleistungsunternehmen gilt BT 12 MaComp, für Versicherer die Sammelverfügung der BaFin.",
     en:"The legal framework consists of the ESAs' Joint Committee guidelines (JC 2014/43, extended by JC 2018/35) and the EIOPA guidelines for insurers and intermediaries. In Germany, BaFin's joint circular 06/2018 implements them for credit institutions, payment and e-money institutions, fund managers and mortgage lenders; investment services firms follow BT 12 MaComp and insurers BaFin's general ruling."}],
  lksg: [
    {de:"Das Lieferkettensorgfaltspflichtengesetz verlangt von Unternehmen ab 1.000 Beschäftigten ein Risikomanagement für Menschenrechts- und Umweltrisiken im eigenen Geschäftsbereich und bei unmittelbaren Zulieferern: Risikoanalyse, Grundsatzerklärung, Präventions- und Abhilfemaßnahmen, ein Beschwerdeverfahren und Dokumentation. Für Finanzinstitute zählen auch Kunden und Portfoliounternehmen unter bestimmten Voraussetzungen zur Lieferkette.",
     en:"The Supply Chain Due Diligence Act requires companies with 1,000 or more employees to run a risk management system for human rights and environmental risks in their own operations and at direct suppliers: risk analysis, policy statement, preventive and remedial measures, a complaints procedure and documentation. For financial institutions, clients and portfolio companies can under certain conditions form part of the supply chain."},
    {de:"Auf EU-Ebene setzt die CSDDD ähnliche Pflichten für sehr große Unternehmen; ihre Anwendung wurde 2025 auf Juli 2028 verschoben und inhaltliche Erleichterungen werden im Omnibus-Verfahren verhandelt. Die Bundesregierung will das LkSG durch ein CSDDD-Umsetzungsgesetz ersetzen; bis dahin soll eine Änderung die Berichtspflicht streichen und Bußgelder auf schwere Verstöße beschränken.",
     en:"At EU level the CSDDD sets similar duties for very large companies; its application was postponed in 2025 to July 2028 and substantive simplifications are being negotiated in the omnibus procedure. The federal government intends to replace the LkSG with a CSDDD implementation act; until then an amendment is to remove the reporting duty and limit fines to serious breaches."}],
  bfsg: [
    {de:"Das Barrierefreiheitsstärkungsgesetz setzt den European Accessibility Act um und erfasst ausdrücklich Bankdienstleistungen für Verbraucher: Kontoführung, Kredite, Zahlungsdienste sowie die zugehörigen Websites, Apps, Geldautomaten und Zahlungsterminals. Informationen müssen wahrnehmbar, bedienbar, verständlich und robust sein, Vertragsunterlagen in verständlicher Sprache vorliegen.",
     en:"The Accessibility Strengthening Act transposes the European Accessibility Act and explicitly covers consumer banking services: account management, credit, payment services and the associated websites, apps, ATMs and payment terminals. Information must be perceivable, operable, understandable and robust, and contract documents must be provided in plain language."},
    {de:"Seit dem 28.06.2025 dürfen neue Dienstleistungen nur noch barrierefrei erbracht werden; für bereits eingesetzte Selbstbedienungsterminals gelten Übergangsfristen. Die Marktüberwachungsbehörden der Länder können Bußgelder verhängen und Dienstleistungen untersagen, Verbände können klagen.",
     en:"Since 28 Jun 2025 new services may only be provided in an accessible form; transition periods apply to self-service terminals already in use. The market surveillance authorities of the Länder can impose fines and prohibit services, and associations can bring collective actions."}],
  mifid: [
    {de:"MiFID II regelt das Wertpapiergeschäft entlang der gesamten Kundenbeziehung: Zielmarktbestimmung in der Produktgovernance, Geeignetheits- und Angemessenheitsprüfung, Offenlegung sämtlicher Kosten und Zuwendungen sowie Aufzeichnungspflichten inklusive Taping.",
     en:"MiFID II governs investment business across the entire client relationship: target market definition in product governance, suitability and appropriateness assessment, disclosure of all costs and inducements, and record-keeping including taping."},
    {de:"Auf Marktseite kommen Handelstransparenz, Best Execution und Transaktionsmeldungen hinzu. Mit der EU-Kleinanlegerstrategie stehen derzeit Zuwendungsregeln, Value-for-Money-Vorgaben und digitale Informationsformate im Zentrum der Reformdebatte.",
     en:"On the market side, trading transparency, best execution and transaction reporting apply. Under the EU retail investment strategy, inducement rules, value-for-money requirements and digital disclosure formats are currently at the heart of reform."}],
  mar: [
    {de:"Die Marktmissbrauchsverordnung verbietet Insidergeschäfte, deren Empfehlung sowie Marktmanipulation und verpflichtet Emittenten zur unverzüglichen Ad-hoc-Veröffentlichung von Insiderinformationen, sofern kein Aufschubgrund vorliegt.",
     en:"The Market Abuse Regulation prohibits insider dealing, recommending it, and market manipulation, and obliges issuers to disclose inside information without delay unless a deferral ground applies."},
    {de:"Flankierend gelten Pflichten zu Insiderlisten, Eigengeschäften von Führungskräften (Managers' Transactions) und Handelsverbotszeiträumen. Wertpapierdienstleister müssen verdächtige Aufträge und Geschäfte über STOR-Meldungen an die Aufsicht melden.",
     en:"This is flanked by duties around insider lists, managers' transactions and closed periods. Investment firms must report suspicious orders and transactions to the supervisor via STORs."}],
  priips: [
    {de:"Die PRIIPs-Verordnung verlangt für verpackte Anlageprodukte und Versicherungsanlageprodukte ein maximal dreiseitiges Basisinformationsblatt (KID) mit standardisierten Angaben zu Risiko, Performance-Szenarien und Kosten.",
     en:"The PRIIPs Regulation requires a key information document (KID) of no more than three pages for packaged retail and insurance-based investment products, with standardised information on risk, performance scenarios and costs."},
    {de:"Das KID muss Privatkunden rechtzeitig vor Vertragsschluss zur Verfügung stehen und laufend aktualisiert werden. Die Methodik der Szenarien und Kostendarstellung ist in technischen Standards detailliert geregelt und Gegenstand fortlaufender Überarbeitung.",
     en:"The KID must be provided to retail investors in good time before conclusion and kept up to date. The methodology for scenarios and cost disclosure is set out in detailed technical standards and subject to ongoing revision."}],
  ecspr: [
    {de:"Die European Crowdfunding Service Providers Regulation (VO (EU) 2020/1503 vom 07.10.2020, anwendbar seit 10.11.2021) schafft ein einheitliches EU-Regime für Schwarmfinanzierungsplattformen: Zulassung durch die nationale Aufsicht (in Deutschland die BaFin), EU-Pass, Pflichten zu Interessenkonflikten, Auslagerung und Verwahrung sowie ein standardisiertes Anlagebasisinformationsblatt (KIIS) je Angebot bis 5 Mio. €. Die begleitende RL (EU) 2020/1504 nimmt zugelassene Dienstleister aus dem MiFID-II-Anwendungsbereich aus.",
     en:"The European Crowdfunding Service Providers Regulation (Regulation (EU) 2020/1503 of 7 Oct 2020, applicable since 10 Nov 2021) creates a uniform EU regime for crowdfunding platforms: authorisation by the national supervisor (BaFin in Germany), an EU passport, duties on conflicts of interest, outsourcing and safekeeping, and a standardised key investment information sheet (KIIS) per offer up to €5m. The accompanying Directive (EU) 2020/1504 exempts authorised providers from MiFID II."},
    {de:"Konkretisiert wird das Regime durch die zwölf delegierten Verordnungen (EU) 2022/2111 bis 2022/2122 vom 13.07.2022 (u. a. Beschwerdeverfahren, Interessenkonflikte, Ausfallquoten, Eingangswissenstest und KIIS) sowie ESMA-Q&As und das ESMA-Register der zugelassenen Dienstleister. In Deutschland hat das Schwarmfinanzierung-Begleitgesetz vom 03.06.2021 die Durchführung geregelt und KAGB, WpHG und VermAnlG angepasst; rein nationale Schwarmfinanzierung nach § 2a VermAnlG besteht daneben fort.",
     en:"The regime is fleshed out by the twelve Delegated Regulations (EU) 2022/2111 to 2022/2122 of 13 Jul 2022 (complaint handling, conflicts of interest, default rates, the entry knowledge test and the KIIS, among others), plus ESMA Q&As and the ESMA register of authorised providers. In Germany, the crowdfunding accompanying act of 3 Jun 2021 governed implementation and amended the KAGB, WpHG and VermAnlG; purely national crowdfunding under § 2a VermAnlG continues alongside."}],
  psd3: [
    {de:"Das PSD3-Paket führt Zahlungsdienste- und E-Geld-Aufsicht in einem Regime zusammen: Die Richtlinie regelt Zulassung und laufende Aufsicht der Institute, während die neue Zahlungsdiensteverordnung (PSR) die Pflichten im Kundenverhältnis unmittelbar und EU-weit einheitlich festlegt.",
     en:"The PSD3 package merges payment services and e-money supervision into one regime: the directive covers authorisation and ongoing supervision, while the new Payment Services Regulation (PSR) sets the customer-facing rules directly and uniformly across the EU."},
    {de:"Inhaltlich werden starke Kundenauthentifizierung und Betrugshaftung verschärft — etwa bei Spoofing zulasten der Banken —, der Kontozugang für Drittdienste technisch neu geordnet und Bargeldversorgung sowie Entgelttransparenz gestärkt. Institute mit bestehender PSD2-Zulassung müssen mit Übergangsfristen neu zugelassen werden.",
     en:"Substantively, strong customer authentication and fraud liability are tightened — including bank liability for spoofing —, third-party access to accounts is technically reorganised, and cash access and fee transparency are strengthened. Institutions holding PSD2 licences must be re-authorised within transition periods."}],
  instant: [
    {de:"Die Verordnung verpflichtet Zahlungsdienstleister im Euroraum, Echtzeitüberweisungen rund um die Uhr zu empfangen und zu senden, und deckelt die Entgelte auf das Niveau herkömmlicher Überweisungen.",
     en:"The regulation obliges payment service providers in the euro area to receive and send instant credit transfers around the clock, and caps charges at the level of ordinary credit transfers."},
    {de:"Vor Ausführung müssen Dienstleister den Empfängernamen mit der IBAN abgleichen (Verification of Payee) und Abweichungen anzeigen; zudem ist die Sanktionslistenprüfung auf ein tägliches Screening der eigenen Kunden umgestellt. Die Pflichten greifen gestaffelt, für Zahlungsinstitute später als für Banken.",
     en:"Before execution, providers must verify the payee name against the IBAN and flag mismatches; sanctions screening shifts to daily screening of their own customers. The duties phase in over time, later for payment institutions than for banks."}],
  mica: [
    {de:"MiCAR schafft erstmals ein einheitliches EU-Regime für Kryptowerte außerhalb der bestehenden Finanzmarktregulierung: Emittenten von E-Geld-Token und vermögenswertereferenzierten Token benötigen eine Zulassung samt Whitepaper-, Eigenmittel- und Reservepflichten.",
     en:"MiCAR creates the first uniform EU regime for crypto-assets outside existing financial regulation: issuers of e-money tokens and asset-referenced tokens need authorisation, with whitepaper, own funds and reserve requirements."},
    {de:"Kryptowertedienstleister (CASPs) — vom Verwahrer bis zur Handelsplattform — unterliegen Zulassung, Organisations- und Wohlverhaltenspflichten sowie Regeln gegen Marktmissbrauch in Kryptowerten. Bestehende nationale Regime wie das deutsche Kryptoverwahrgeschäft gehen im EU-Regime auf.",
     en:"Crypto-asset service providers (CASPs) — from custodians to trading platforms — are subject to authorisation, organisational and conduct duties, plus market abuse rules for crypto-assets. Existing national regimes such as Germany's crypto custody licence are absorbed into the EU framework."}],
  dltpilot: [
    {de:"Die DLT-Pilotregelung (VO (EU) 2022/858, anwendbar seit dem 23.03.2023) erlaubt es Wertpapierfirmen, Marktbetreibern und Zentralverwahrern, Handelssysteme (DLT-MTF), Abwicklungssysteme (DLT-SS) oder kombinierte Handels- und Abwicklungssysteme (DLT-TSS) für tokenisierte Finanzinstrumente zu betreiben — mit befristeten, an Auflagen geknüpften Ausnahmen von MiFIR und CSDR, etwa vom Intermediärszwang und von einzelnen Meldepflichten. Zulässig sind nur kleinere Emissionen (u. a. Aktien, Anleihen, Fondsanteile) unterhalb fester Schwellenwerte; die besondere Erlaubnis erteilt die nationale Aufsicht — in Deutschland die BaFin —, ESMA gibt Leitlinien und Stellungnahmen dazu ab und führt das Register der zugelassenen DLT-Marktinfrastrukturen.",
     en:"The DLT Pilot Regime (Regulation (EU) 2022/858, applicable since 23 March 2023) allows investment firms, market operators and CSDs to operate trading venues (DLT MTF), settlement systems (DLT SS) or combined trading and settlement systems (DLT TSS) for tokenised financial instruments — under temporary, condition-bound exemptions from MiFIR and CSDR, for instance from mandatory intermediation and certain reporting duties. Only smaller issuances (shares, bonds, fund units, among others) below fixed thresholds qualify; the specific permission is granted by the national supervisor — BaFin in Germany — while ESMA issues guidelines and opinions and maintains the register of authorised DLT market infrastructures."},
    {de:"In Deutschland schafft das eWpG seit 2021 die zivilrechtliche Grundlage für elektronische Wertpapiere ohne Urkunde: Zentralregisterwertpapiere bei einer Wertpapiersammelbank sowie Kryptowertpapiere in einem dezentral geführten Kryptowertpapierregister, dessen Führung eine BaFin-Erlaubnis nach dem KWG voraussetzt; das Zukunftsfinanzierungsgesetz hat das Regime auf elektronische Aktien erweitert. Parallel erproben EZB und Bundesbank — u. a. mit der Trigger-Lösung — die Abwicklung von DLT-Transaktionen in Zentralbankgeld; aus der Auswertung der Pilotregelung durch ESMA und EU-Kommission kann eine Verlängerung oder Überführung in ein dauerhaftes Regime folgen.",
     en:"In Germany, the eWpG has since 2021 provided the civil-law basis for electronic securities without a physical certificate: central register securities held with a central securities depository, and crypto securities recorded in a decentralised crypto securities register whose operation requires a BaFin licence under the KWG; the Future Financing Act extended the regime to electronic shares. In parallel, the ECB and the Bundesbank — including via the trigger solution — are testing settlement of DLT transactions in central bank money; the evaluation of the pilot regime by ESMA and the European Commission may lead to an extension or a permanent framework."}],
  aifmd2: [
    {de:"Die AIFMD-Novelle verschärft die Regeln für Fondsverwalter: Delegationsstrukturen müssen substanzhaltig bleiben und werden aufsichtlich gemeldet, kreditvergebende Fonds erhalten erstmals einen harmonisierten Rahmen mit Risikodiversifizierungs- und Rückbehaltspflichten.",
     en:"The AIFMD review tightens the rules for fund managers: delegation structures must retain substance and are reported to supervisors, and loan-originating funds get a harmonised framework with risk diversification and retention requirements for the first time."},
    {de:"Offene Fonds müssen künftig mindestens zwei Liquiditätsmanagement-Instrumente aus einem harmonisierten Katalog vorsehen. Die Änderungen gelten parallel für OGAW-Verwaltungsgesellschaften und sind bis 2026 in nationales Recht umzusetzen.",
     en:"Open-ended funds must in future provide for at least two liquidity management tools from a harmonised catalogue. The changes apply in parallel to UCITS management companies and must be transposed into national law by 2026."}],
  eltif: [
    {de:"Der ELTIF ist das EU-Produktvehikel für langfristige Anlagen in Infrastruktur, Sachwerte und nicht börsennotierte Unternehmen. Die Reform (ELTIF 2.0) hat Anlagegrenzen gelockert, Dachfonds- und Master-Feeder-Strukturen geöffnet und den Vertrieb an Privatanleger erheblich vereinfacht.",
     en:"The ELTIF is the EU product vehicle for long-term investment in infrastructure, real assets and unlisted companies. The reform (ELTIF 2.0) relaxed investment limits, opened fund-of-funds and master-feeder structures and considerably simplified retail distribution."},
    {de:"Für Privatanleger entfallen Mindestanlagesummen und Vermögensschwellen; stattdessen greift die MiFID-Geeignetheitsprüfung. Technische Standards regeln Rücknahmemöglichkeiten und Liquiditätsvorgaben für offene ELTIF-Strukturen.",
     en:"Minimum investment amounts and wealth thresholds for retail investors were abolished in favour of the MiFID suitability test. Technical standards govern redemption options and liquidity requirements for open-ended ELTIF structures."}],
  mmf: [
    {de:"Die Geldmarktfonds-Verordnung regelt Zulassung, zulässige Vermögenswerte, Portfoliozusammensetzung und Bewertung von Geldmarktfonds und unterscheidet zwischen Fonds mit konstantem, schwankungsarmem und variablem Nettoinventarwert.",
     en:"The Money Market Funds Regulation governs authorisation, eligible assets, portfolio composition and valuation of MMFs, distinguishing between constant, low-volatility and variable NAV funds."},
    {de:"Tägliche und wöchentliche Liquiditätsquoten, Stresstests und Know-your-Customer-Pflichten sollen Anteilsrückgaben auch in Stressphasen sicherstellen. Auf EU-Ebene wird eine Reform diskutiert, die Liquiditätspuffer erhöhen und die Kopplung von Schwellenwerten an Rücknahmesperren lösen soll.",
     en:"Daily and weekly liquidity ratios, stress testing and know-your-customer duties are designed to keep funds redeemable even in stress. An EU reform is under discussion to raise liquidity buffers and decouple thresholds from redemption gates."}],
  sfdr: [
    {de:"Die Offenlegungsverordnung verpflichtet Finanzmarktteilnehmer und Berater, Nachhaltigkeitsinformationen auf Unternehmens- und Produktebene offenzulegen: den Umgang mit Nachhaltigkeitsrisiken, nachteilige Auswirkungen (PAI) sowie vorvertragliche und periodische Produktangaben.",
     en:"The disclosure regulation obliges financial market participants and advisers to disclose sustainability information at entity and product level: the handling of sustainability risks, principal adverse impacts (PAI), and pre-contractual and periodic product disclosures."},
    {de:"Die Einstufung von Produkten nach Artikel 8 und 9 hat sich faktisch zu einem Labelsystem entwickelt, was die EU-Kommission mit der laufenden SFDR-Überarbeitung durch echte Produktkategorien ersetzen will. Die technischen Standards mit den Meldebögen werden parallel überarbeitet.",
     en:"The Article 8 and 9 classification has de facto evolved into a labelling system, which the European Commission intends to replace with genuine product categories in the ongoing SFDR review. The technical standards containing the templates are being revised in parallel."}],
  itsrep: [
    {de:"Die Durchführungsverordnung (EU) 2024/3117 (Nachfolgerin der DVO 2021/451 und 680/2014, in der Praxis „ITS on Supervisory Reporting“) legt EU-weit einheitlich fest, welche Daten Institute in welchen Formaten und Intervallen an die Aufsicht melden: COREP für Eigenmittel und Liquidität, FINREP für Finanzinformationen sowie Meldungen zu Großkrediten, Leverage Ratio und Verschuldung. Die zugehörigen Meldebögen, Taxonomien und Validierungsregeln veröffentlicht die EBA als Reporting Framework.",
     en:"Implementing Regulation (EU) 2024/3117 (successor to Regulations 2021/451 and 680/2014, commonly called the ITS on supervisory reporting) defines uniformly across the EU which data institutions report to supervisors, in which formats and at which intervals: COREP for own funds and liquidity, FINREP for financial information, plus large exposures, leverage ratio and funding reports. The EBA publishes the associated templates, taxonomies and validation rules as its reporting framework."},
    {de:"Mit CRR III werden die Meldebögen umfassend angepasst, etwa für den Output Floor und die neuen Risikoansätze. Die EBA treibt parallel die Integration des Meldewesens voran, um Doppelmeldungen zu reduzieren und Definitionen über Aufsichts- und Statistikmeldungen hinweg zu vereinheitlichen.",
     en:"With CRR III the templates are being comprehensively revised, for instance for the output floor and the new risk approaches. In parallel, the EBA is advancing integrated reporting to reduce duplicate submissions and align definitions across supervisory and statistical reporting."}],
  anacredit: [
    {de:"AnaCredit ist das granulare Kreditmelderegister des Eurosystems: Banken melden kreditnehmerbezogene Einzeldaten zu Krediten an juristische Personen ab 25.000 Euro, in Deutschland über die Bundesbank.",
     en:"AnaCredit is the Eurosystem's granular credit register: banks report borrower-level data on loans to legal entities from €25,000, in Germany via the Bundesbank."},
    {de:"Die Daten speisen Geldpolitik, Finanzstabilitätsanalyse und Bankenaufsicht. Meldepflichtige müssen auf konsistente Stammdaten und die Verknüpfung über LEI-Kennungen achten; Erweiterungen des Merkmalskatalogs und Qualitätsanforderungen werden laufend fortgeschrieben.",
     en:"The data feeds monetary policy, financial stability analysis and banking supervision. Reporting agents must ensure consistent master data and linkage via LEI identifiers; extensions to the attribute catalogue and quality requirements are updated continuously."}],
  solvency: [
    {de:"Solvency II ist das risikobasierte Aufsichtsregime für Versicherer mit drei Säulen: quantitative Kapitalanforderungen (SCR/MCR) auf Basis einer marktnahen Bewertung, qualitative Governance-Anforderungen samt ORSA sowie umfangreiche Berichts- und Offenlegungspflichten.",
     en:"Solvency II is the risk-based supervisory regime for insurers with three pillars: quantitative capital requirements (SCR/MCR) based on market-consistent valuation, qualitative governance requirements including ORSA, and extensive reporting and disclosure duties."},
    {de:"Die laufende Überprüfung passt unter anderem Zinsextrapolation, Volatilitätsanpassung und Proportionalitätsregeln an und führt neue Vorgaben zu Nachhaltigkeitsrisiken und makroprudenzieller Aufsicht ein. Parallel entsteht mit der IRRD ein eigenes Sanierungs- und Abwicklungsregime für Versicherer.",
     en:"The ongoing review adjusts interest rate extrapolation, the volatility adjustment and proportionality rules, and introduces new requirements on sustainability risk and macroprudential supervision. In parallel, the IRRD creates a dedicated recovery and resolution regime for insurers."}],
  absfinag: [
    {de:"Das Absatzfinanzierungsaufsichtsgesetz ist Teil des Gesetzes zur Umsetzung der Verbraucherkreditrichtlinie 2023 (CCD II, RL (EU) 2023/2225), das der Bundestag am 17.04.2026 beschlossen hat. Es unterwirft erstmals Unternehmen der Aufsicht der BaFin, die Verbrauchern ohne Banklizenz Kredite in Form von Zahlungsaufschüben, Ratenzahlungen oder Rechnungskauf gewähren – typischerweise Händler, Plattformen und Buy-now-pay-later-Anbieter. Diese Absatzfinanzierer müssen sich bei der BaFin registrieren und die Wohlverhaltens- und Kreditwürdigkeitsvorgaben der CCD II einhalten; Kreditinstitute, die vorab die Abtretung der Zahlungsansprüche mit Absatzfinanzierern vereinbaren, unterliegen einer Meldepflicht nach § 6 Absatz 2 AbsFinAG.",
     en:"The Sales Financing Supervision Act (AbsFinAG) is part of the act implementing the 2023 Consumer Credit Directive (CCD II, Directive (EU) 2023/2225), adopted by the Bundestag on 17 April 2026. For the first time it brings under BaFin supervision companies that grant consumer credit without a banking licence in the form of deferred payment, instalments or invoice purchase – typically merchants, platforms and buy-now-pay-later providers. These sales-financing providers must register with BaFin and comply with the CCD II conduct and creditworthiness requirements; credit institutions that agree in advance to take assignment of the payment claims are subject to a reporting duty under § 6(2) AbsFinAG."},
    {de:"Ausgenommen sind insbesondere Kleinst-, kleine und mittlere Unternehmen, die zinsfreie Zahlungsaufschübe mit nur begrenzten Kosten ausschließlich für den Erwerb ihrer eigenen Waren oder Dienstleistungen gewähren (§ 4 AbsFinAG). Vorsätzliche oder fahrlässige Verstöße können mit Bußgeldern bis 500.000 Euro geahndet werden (§ 8 AbsFinAG). Die neuen Regeln gelten ab dem 20.11.2026; für bestehende Anbieter sieht § 10 AbsFinAG eine Übergangsfrist von bis zu zwölf Monaten, längstens bis zum 20.11.2027, vor. Die BaFin hat am 31.08.2026 einen Entscheidungsbaum zur Registrierungs- und Meldepflicht sowie die Antrags- und Meldeformulare veröffentlicht.",
     en:"Exempt are in particular micro, small and medium-sized enterprises that grant interest-free deferrals with only limited costs exclusively for the purchase of their own goods or services (§ 4 AbsFinAG). Intentional or negligent breaches can be fined up to EUR 500,000 (§ 8 AbsFinAG). The new rules apply from 20 November 2026; for existing providers § 10 AbsFinAG provides a transition period of up to twelve months, ending no later than 20 November 2027. On 31 August 2026 BaFin published a decision tree on registration and reporting duties together with the application and reporting forms."}],
  irrd: [
    {de:"Die Insurance Recovery and Resolution Directive (RL (EU) 2025/1 vom 27.11.2024, veröffentlicht im Amtsblatt am 08.01.2025) schafft erstmals einen EU-weit harmonisierten Rahmen für die Sanierung und Abwicklung von Versicherungs- und Rückversicherungsunternehmen nach dem Vorbild der BRRD für Banken. Versicherer, die einen wesentlichen Marktanteil abdecken, müssen präventive Sanierungspläne aufstellen; nationale Abwicklungsbehörden erstellen Abwicklungspläne, prüfen die Abwicklungsfähigkeit und erhalten Instrumente wie Run-off, Übertragung von Portfolios und Herabschreibung oder Umwandlung von Kapitalinstrumenten.",
     en:"The Insurance Recovery and Resolution Directive (Directive (EU) 2025/1 of 27 November 2024, published in the Official Journal on 8 January 2025) creates for the first time an EU-wide harmonised framework for the recovery and resolution of insurance and reinsurance undertakings, modelled on the BRRD for banks. Insurers covering a significant share of the market must draw up pre-emptive recovery plans; national resolution authorities prepare resolution plans, assess resolvability and receive tools such as run-off, portfolio transfer and the write-down or conversion of capital instruments."},
    {de:"Die Mitgliedstaaten müssen die Richtlinie bis zum 29.01.2027 umsetzen; die Vorschriften gelten ab dem 30.01.2027. EIOPA konkretisiert das Regime durch technische Regulierungsstandards und Leitlinien – etwa zu den Kriterien für die Identifizierung kritischer Funktionen, zur Bewertung im Abwicklungsfall und zum Inhalt der Sanierungs- und Abwicklungspläne – und hat dazu ab 2025 mehrere Konsultationen durchgeführt. In Deutschland ist die BaFin als Abwicklungsbehörde für den Versicherungssektor vorgesehen; die Umsetzung erfolgt im VAG.",
     en:"Member States must transpose the directive by 29 January 2027; its provisions apply from 30 January 2027. EIOPA fleshes out the regime through regulatory technical standards and guidelines – for instance on the criteria for identifying critical functions, on valuation in resolution and on the content of recovery and resolution plans – and has run several consultations on these since 2025. In Germany, BaFin is envisaged as the resolution authority for the insurance sector, with transposition through the VAG."}],
  idd: [
    {de:"Die IDD harmonisiert den Versicherungsvertrieb in der EU: Vermittler und Versicherer müssen ehrlich, redlich und im bestmöglichen Kundeninteresse handeln, Wünsche und Bedürfnisse prüfen und vor Abschluss ein Produktinformationsblatt aushändigen.",
     en:"The IDD harmonises insurance distribution in the EU: intermediaries and insurers must act honestly, fairly and in the customer's best interest, assess demands and needs, and provide a product information document before conclusion."},
    {de:"Für Versicherungsanlageprodukte gelten zusätzlich MiFID-ähnliche Regeln zu Interessenkonflikten, Zuwendungen und Geeignetheit; die Produktfreigabe verlangt einen definierten Zielmarkt. Die EU-Kleinanlegerstrategie stellt Provisionsregeln und Preis-Leistungs-Vorgaben derzeit auf den Prüfstand.",
     en:"For insurance-based investment products, MiFID-style rules on conflicts of interest, inducements and suitability apply in addition; product approval requires a defined target market. The EU retail investment strategy is currently re-examining commission rules and value-for-money requirements."}],
  emir: [
    {de:"EMIR verpflichtet finanzielle Gegenparteien — darunter Banken, Wertpapierinstitute, Versicherer sowie OGAW und AIF mit ihren Verwaltern — standardisierte OTC-Derivate über zugelassene zentrale Gegenparteien (CCPs) zu clearen. Für nicht geclearte Geschäfte gelten Risikominderungstechniken wie rechtzeitige Bestätigung, Portfolioabstimmung und der bilaterale Austausch von Sicherheiten; sämtliche Derivatekontrakte sind an Transaktionsregister zu melden.",
     en:"EMIR obliges financial counterparties — including banks, investment firms, insurers and UCITS and AIFs together with their managers — to clear standardised OTC derivatives through authorised central counterparties (CCPs). Uncleared trades are subject to risk mitigation techniques such as timely confirmation, portfolio reconciliation and bilateral margining; all derivative contracts must be reported to trade repositories."},
    {de:"Die EMIR-3.0-Novelle führt das aktive Konto ein: Marktteilnehmer mit wesentlichen Positionen in bestimmten Euro-Zinsderivaten müssen einen Teil davon über EU-CCPs clearen, um die Abhängigkeit von Drittstaaten-Clearinghäusern zu verringern. Daneben werden Meldewesen und Intragruppen-Ausnahmen vereinfacht. Für Fonds greifen die Pflichten auf Fondsebene — in der Verantwortung der Verwaltungsgesellschaft.",
     en:"The EMIR 3.0 reform introduces the active account: market participants with material positions in certain euro interest rate derivatives must clear part of them through EU CCPs to reduce reliance on third-country clearing houses. Reporting and intragroup exemptions are simplified alongside. For funds, the duties apply at fund level — under the responsibility of the management company."}],
  bmr: [
    {de:"Die Benchmark-Verordnung regelt Erstellung, Bereitstellung und Verwendung von Referenzwerten: Administratoren benötigen eine Zulassung oder Registrierung und müssen Governance-, Methodik- und Kontrollanforderungen erfüllen. Beaufsichtigte Verwender — etwa Fondsverwalter, die Indizes nachbilden oder die Wertentwicklung daran messen, und Emittenten strukturierter Produkte — dürfen nur Referenzwerte zugelassener Administratoren einsetzen.",
     en:"The Benchmark Regulation governs the provision and use of benchmarks: administrators need authorisation or registration and must meet governance, methodology and control requirements. Supervised users — such as fund managers tracking indices or measuring performance against them, and issuers of structured products — may only use benchmarks from authorised administrators."},
    {de:"Verwender müssen robuste schriftliche Ausweichpläne für den Wegfall oder die wesentliche Änderung eines Referenzwerts vorhalten und in Prospekten auf die Registrierung des Administrators hinweisen. Die laufende Überarbeitung beschränkt den Anwendungsbereich künftig im Wesentlichen auf kritische und signifikante Benchmarks sowie EU-Klima-Benchmarks und erleichtert die Nutzung von Drittstaaten-Referenzwerten.",
     en:"Users must maintain robust written fallback plans for the cessation or material change of a benchmark and reference the administrator's registration in prospectuses. The ongoing review essentially narrows the scope to critical and significant benchmarks plus EU climate benchmarks, and eases the use of third-country benchmarks."}],
  dsgvo: [
    {de:"Die DSGVO regelt jede Verarbeitung personenbezogener Daten: Sie verlangt eine Rechtsgrundlage, Zweckbindung und Datenminimierung, sichert Betroffenenrechte wie Auskunft und Löschung und verpflichtet zu technischen und organisatorischen Schutzmaßnahmen. Datenpannen sind binnen 72 Stunden der Aufsichtsbehörde zu melden.",
     en:"The GDPR governs any processing of personal data: it requires a legal basis, purpose limitation and data minimisation, secures data subject rights such as access and erasure, and mandates technical and organisational safeguards. Data breaches must be reported to the supervisory authority within 72 hours."},
    {de:"Für Finanzunternehmen sind vor allem Auftragsverarbeitung bei IT-Dienstleistern, Drittlandtransfers, Scoring und automatisierte Einzelentscheidungen sowie das Zusammenspiel mit aufsichtsrechtlichen Aufbewahrungspflichten relevant. Leitlinien des EDSA und Positionen von BfDI und Landesbehörden konkretisieren die Anforderungen laufend.",
     en:"For financial firms, the key issues are processing by IT service providers, third-country transfers, scoring and automated individual decisions, and the interplay with regulatory retention duties. EDPB guidelines and positions of the BfDI and state authorities continuously flesh out the requirements."}],
  aiact: [
    {de:"Die KI-Verordnung folgt einem risikobasierten Ansatz: Bestimmte Praktiken sind verboten, Hochrisiko-Systeme unterliegen Anforderungen an Datenqualität, Dokumentation, menschliche Aufsicht und Robustheit, und für generative KI-Modelle gelten eigene Transparenz- und Urheberrechtspflichten. Die Pflichten greifen gestaffelt bis 2027.",
     en:"The AI Act follows a risk-based approach: certain practices are banned, high-risk systems face requirements on data quality, documentation, human oversight and robustness, and general-purpose AI models carry their own transparency and copyright duties. Obligations phase in until 2027."},
    {de:"Im Finanzsektor gelten insbesondere Kreditwürdigkeitsprüfung und Risikobewertung bei Lebens- und Krankenversicherungen als Hochrisiko-Anwendungen. Betreiber müssen KI-Kompetenz sicherstellen und ihre Systeme inventarisieren; die Aufsicht über Finanzunternehmen soll weitgehend bei den Finanzaufsichtsbehörden liegen.",
     en:"In finance, creditworthiness assessment and risk pricing in life and health insurance count as high-risk use cases. Deployers must ensure AI literacy and inventory their systems; supervision of financial entities is expected to sit largely with the financial supervisors."}],
  eidas2: [
    {de:"eIDAS 2 verpflichtet die Mitgliedstaaten, ihren Bürgerinnen und Bürgern eine europäische Digitale-Identität-Wallet (EUDI-Wallet) anzubieten, mit der man sich EU-weit ausweisen, Nachweise teilen und qualifiziert elektronisch signieren kann. Durchführungsrechtsakte legen die technischen Standards fest.",
     en:"eIDAS 2 obliges member states to offer their citizens a European Digital Identity Wallet (EUDI wallet) for EU-wide identification, sharing of attestations and qualified electronic signatures. Implementing acts set the technical standards."},
    {de:"Banken und Zahlungsdienstleister müssen die Wallet dort akzeptieren, wo eine starke Kundenauthentifizierung verlangt wird — das betrifft Onboarding, Login und Zahlungsfreigabe. Zugleich eröffnet die Wallet neue Wege für die geldwäscherechtliche Identifizierung ohne Video-Ident.",
     en:"Banks and payment providers must accept the wallet wherever strong customer authentication is required — affecting onboarding, login and payment authorisation. At the same time, the wallet opens new routes for AML identification without video identification."}],
  csrd: [
    {de:"Die CSRD verankert die Nachhaltigkeitsberichterstattung im Lagebericht: Berichtet wird nach den europäischen Standards (ESRS) über Umwelt-, Sozial- und Governance-Themen entlang der doppelten Wesentlichkeit — also Auswirkungen des Unternehmens und finanzielle Risiken aus Nachhaltigkeitsthemen. Der Bericht ist extern zu prüfen.",
     en:"The CSRD anchors sustainability reporting in the management report: companies report under the European standards (ESRS) on environmental, social and governance topics along double materiality — the company's impacts and the financial risks from sustainability matters. The report is subject to external assurance."},
    {de:"Mit dem Omnibus-Paket werden Anwenderkreis, Zeitplan und Datenpunkte derzeit deutlich verschlankt; die deutsche Umsetzung läuft parallel. Für Finanzunternehmen bleibt die CSRD Datenlieferant für SFDR- und Säule-3-Angaben, weshalb Änderungen unmittelbar auf die eigenen Offenlegungen durchschlagen.",
     en:"The omnibus package is currently slimming down scope, timeline and data points, with German transposition running in parallel. For financial firms the CSRD remains the data source for SFDR and Pillar 3 disclosures, so changes feed straight through to their own reporting."}],
  consumer: [
    {de:"Der Verbraucherschutz im Finanzgeschäft bündelt die zivilrechtlichen Pflichten gegenüber Privatkunden: vorvertragliche Information, Kreditwürdigkeitsprüfung, Widerrufsrechte und die AGB-Kontrolle durch die Rechtsprechung. Die neue Verbraucherkreditrichtlinie CCD II erweitert den Anwendungsbereich auf Buy-now-pay-later und Kleinkredite.",
     en:"Consumer protection in finance bundles the civil-law duties towards retail clients: pre-contractual information, creditworthiness assessment, withdrawal rights and judicial review of standard terms. The new Consumer Credit Directive CCD II extends the scope to buy-now-pay-later and small loans."},
    {de:"Die CCD II ist bis November 2025 umzusetzen und ab November 2026 anzuwenden; parallel treiben BGH- und EuGH-Rechtsprechung etwa zu Prämiensparverträgen, Kontoentgelten und Widerrufsinformationen die Anforderungen fort. Auch die BaFin greift Verbraucherschutzthemen zunehmend aufsichtlich auf.",
     en:"The CCD II must be transposed by November 2025 and applies from November 2026; in parallel, Federal Court of Justice and CJEU case law — on premium savings contracts, account fees and withdrawal information — keeps advancing the requirements. BaFin, too, increasingly addresses consumer protection through supervision."}],
};

